        database: cfg.get<string>('DB_DATABASE'),
        entities: [ 
	        User, 
        ],
        synchronize: false, // 운영에서는 반드시 false
        logging: true,
      }),
    }),
    TypeOrmModule.forFeature([User]),
    AuthModule,
    UserModule,
  ],
})
